let term, value;
const mode = aFilterValue.mode;

// Show only messages that have no tags assigned.
if (mode === "NONE") {
  term = aTermCreator.createTerm();
  term.attrib = Ci.nsMsgSearchAttrib.Keywords;
  value = term.value;
  value.str = "";
  term.value = value;
  term.op = Ci.nsMsgSearchOp.IsEmpty;
  term.booleanAnd = true;
  aTerms.push(term);
  return null;
}
